#!/usr/bin/env bash
# Autogenerated test: runs as the remote user inside a container built from each compatibility image with
# lxc-distrobuilder installed with default options, in the container the feature's metadata gives.
set -euo pipefail

# shellcheck source=/dev/null
source dev-container-features-test-lib
# shellcheck source=/dev/null
source "$(dirname "$0")/helpers.sh"

# The release the latest-release link names when the test runs; a release between build and test fails once.
latest="$(latest_release)"

check "command -v distrobuilder resolves to /usr/local/bin/distrobuilder" \
  test "$(command -v distrobuilder)" = "${DB_TARGET}"
check "distrobuilder --version as root prints the latest release, which is also the recorded one" \
  reports_version "${latest}"
check "the container holds SYS_ADMIN and is not privileged" holds_sys_admin_only
check "the container runs without an AppArmor profile" runs_without_apparmor
check "the tools for container images are on root's PATH" on_root_path debootstrap rsync gpg mksquashfs xz
check "the tools of vmSupport are not installed by default" not_on_root_path mkfs.btrfs sgdisk qemu-img
check "the tools of windowsSupport are not installed by default" not_on_root_path hivexregedit wimlib-imagex genisoimage
check "no Go toolchain is left in the image" no_toolchain_left
check "no GnuPG or Go directory is left in a home directory" no_build_leftovers_in_homes
check "root builds a container image with distrobuilder build-incus" builds_container_image

reportResults
